<template>
  <div class="safe-center-mail">
    <title-line :title="title" />
    <div class="content">
      <div class="box">
        <van-form validate-trigger="onSubmit" @submit="onSubmit">
          <!-- <van-field
            v-model="oldloginpwd"
            name="登录密码"
            type="text"
            label=""
            placeholder="请输入登录密码"
            autocomplete="off"
            :rules="[{ required: true, message: '请输入原密码' }]"
          /> -->
          <div class="title">{{ $t('aqzx.aqzx53') }}</div>
          <van-field
            v-model="drawpwd"
            style="margin-top:10px"
            :type="passwordType"
            name="提现密码"
            label=""
            autocomplete="off"
            :placeholder="$t('txym.txym55')"
            :rules="[{ required: true, message: $t('txym.txym55') }]"
          >
            <template slot="right-icon">
              <span class="soltseye" @click="switchPasswordType">
                <van-icon v-if="passwordType==='password'" name="eye" />
                <van-icon v-else name="closed-eye" />
              </span>
            </template>
          </van-field>
          <div class="title">{{ $t('aqzx.aqzx53') }}</div>
          <van-field
            v-model="confirmpwd"
            style="margin-top:10px"
            :type="passwordType1"
            name="确认提现密码"
            label=""
            autocomplete="off"
            :placeholder="$t('txym.txym56')"
            :rules="[{ required: true, message: $t('txym.txym56') }]"
          >
            <template slot="right-icon">
              <span class="soltseye" @click="switchPasswordType1">
                <van-icon v-if="passwordType1==='password'" name="eye" />
                <van-icon v-else name="closed-eye" />
              </span>
            </template>
          </van-field>
          <!-- <div class="tips" style="margin:20px 0 30px 0">
            <div class="warning_icon" />
            <span>为了保障您的账号和资金安全，请绑定邮箱</span>
          </div> -->
          <div style="margin: 40px auto 10px;">
            <van-button
              class="btn-bg"
              block
              type="info"
              native-type="submit"
            >提交</van-button>
          </div>
          <!-- <div class="forgetPsd">忘记密码</div> -->
        </van-form>
      </div>
    </div>

  </div>
</template>
<script>
import TitleLine from './modules/TitleLine'
import { setdrawpwd } from '@/api/safe'
export default {
  components: {
    TitleLine
  },
  props: {
  },
  data() {
    return {
      title: this.$t('txym.txym31'), // '设置提现密码',
      loginPsd: '',
      drawpwd: '',
      confirmpwd: '',
      passwordType: 'password',
      passwordType1: 'password'
    }
  },
  methods: {
    switchPasswordType() {
      this.passwordType = this.passwordType === 'password' ? 'text' : 'password'
    },
    switchPasswordType1() {
      this.passwordType1 = this.passwordType1 === 'password' ? 'text' : 'password'
    },
    // goMore() {
    //   this.$router.push({ path: '/rechargeRecord' })
    // }
    onSubmit() {
      if (this.drawpwd !== this.confirmpwd) {
        this.$toast(this.$t('aqzx.aqzx56'))
        return false
      }
      setdrawpwd({ drawpwd: this.drawpwd }).then(res => {
        if (res.status === '1') {
          this.$toast(this.$t('aqzx.aqzx49'))
          setTimeout(() => {
            if (this.$route.query.type === '1') {
              this.$router.push({ path: '/reflect' })
            } else {
              this.$router.push({ path: '/safeCenter' })
            }
          }, 2000)
        }
      })
    }
  }

}
</script>
<style lang="scss" scoped>
.safe-center-mail {
    min-height: 100vh;
    width: 100%;
    background: var(--inner-bg-color);
    background-position: 0% 0%;
    background-size: 100% 100%;
    overflow: hidden;
    font-size: 24px;
    color: #fff;
    .containers{
    position: relative;
    // padding: 0px 30px 0px;
    }
    .content{
        margin: auto 28px;
        .box {
          margin-top: 36px;
          padding: 40px;
          border-radius: 28px;
          background: rgba(241, 229, 255,0.12);
          border-radius: 8px;
        .title {
            margin-bottom: 16px;
            font-family: PingFangSC-Regular;
            font-size: 28px;
            color: rgba(255, 255, 255,0.75);
            letter-spacing: 0;
            line-height: 40px;
            font-weight: 400;
        }
        .title:not(:first-child){
          margin-top: 40px;
        }
        .tips {
            color: #fff;
            position: relative;
            .warning_icon {
                position: absolute;
                top: 6px;
                width: 20px;
                height: 20px;
                background-image: url(~@/assets/portal/warning_icon.png);
                background-position: 0% 0%;
                background-size: 100% 100%;
                background-repeat: no-repeat;
            }
            span {
                margin-left: 28px;
            }
        }
        .forgetPsd{
            text-align: center;
            font-family: PingFangSC-Regular;
            font-size: 28px;
            color: #00B7FF;
            font-weight: 400;
        }
     }
    }

}
</style>
